&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Les arch&#233;types de pr&#234;tre&lt;a class=&quot;headeranchor&quot; id=&quot;Les_arch&#233;types_de_pr&#234;tre_0&quot; href=&quot;#Les_arch&#233;types_de_pr&#234;tre_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&amp;nbsp;Retour &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre.html&quot; title=&quot;Le pr&#234;tre&quot;&gt;classe&lt;/a&gt;.
&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ap&#244;tre-D&#233;moniaque-(Pr&#234;tre).html&quot; title=&quot;Ap&#244;tre d&#233;moniaque&quot;&gt;Ap&#244;tre d&#233;moniaque&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Drow-(Race).html&quot; title=&quot;Les drows&quot;&gt;Drow&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cardinal-(Pr&#234;tre).html&quot; title=&quot;Cardinal&quot;&gt;Cardinal&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;rudit-Du-Savoir-(Pr&#234;tre).html&quot; title=&quot;&#201;rudit du savoir&quot;&gt;&#201;rudit du savoir&lt;/a&gt; (RSE)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;vang&#233;liste-(Pr&#234;tre).html&quot; title=&quot;&#201;vang&#233;liste&quot;&gt;&#201;vang&#233;liste&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gu&#233;risseur-Mis&#233;ricordieux-(Pr&#234;tre).html&quot; title=&quot;Gu&#233;risseur mis&#233;ricordieux&quot;&gt;Gu&#233;risseur mis&#233;ricordieux&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Des-Forges-(Pr&#234;tre).html&quot; title=&quot;Ma&#238;tre des forges&quot;&gt;Ma&#238;tre des forges&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Nain.html&quot; title=&quot;Les nains&quot;&gt;Nain&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;P&#232;lerin-Varisien-(Pr&#234;tre).html&quot; title=&quot;P&#232;lerin nomade&quot;&gt;P&#232;lerin nomade&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre-Clandestin-(Pr&#234;tre).html&quot; title=&quot;Pr&#234;tre clandestin&quot;&gt;Pr&#234;tre clandestin&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre-Clo&#238;tr&#233;-(Pr&#234;tre).html&quot; title=&quot;Pr&#234;tre clo&#238;tr&#233;&quot;&gt;Pr&#234;tre clo&#238;tr&#233;&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre-Mend&#233;vien-(Pr&#234;tre).html&quot; title=&quot;Pr&#234;tre crois&#233;&quot;&gt;Pr&#234;tre crois&#233;&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;ceptacle-Fi&#233;lon-(Pr&#234;tre).html&quot; title=&quot;R&#233;ceptacle fi&#233;lon&quot;&gt;R&#233;ceptacle fi&#233;lon&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Tieffelin-(Race).html&quot; title=&quot;Les tieffelins&quot;&gt;Tieffelin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Saint-Combattant-(Pr&#234;tre).html&quot; title=&quot;Saint combattant&quot;&gt;Saint combattant&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Seigneur-Des-Morts-Vivants-(Pr&#234;tre).html&quot; title=&quot;Seigneur des morts-vivants&quot;&gt;Seigneur des morts-vivants&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;S&#233;paratiste-(Pr&#234;tre).html&quot; title=&quot;S&#233;paratiste&quot;&gt;S&#233;paratiste&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Strat&#232;ge-Divin-(Pr&#234;tre).html&quot; title=&quot;Strat&#232;ge divin&quot;&gt;Strat&#232;ge divin&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Th&#233;ologien-(Pr&#234;tre).html&quot; title=&quot;Th&#233;ologien&quot;&gt;Th&#233;ologien&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Th&#233;urge-Eccl&#233;siastique-(Pr&#234;tre).html&quot; title=&quot;Th&#233;urge eccl&#233;siastique&quot;&gt;Th&#233;urge eccl&#233;siastique&lt;/a&gt; (MCA)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;L’&#233;vang&#233;liste est le porte-parole de sa religion dans le vaste monde. Certains pr&#234;tres aident &#224; entretenir la foi dans le cœur des fid&#232;les mais l’&#233;vang&#233;liste annonce la glorieuse venue de son dieu et appelle les gens &#224; se rassembler pour entendre la v&#233;rit&#233; ou &#224; ob&#233;ir &#224; l’appel de la guerre sainte et &#224; partir en croisade contre les ennemis de l’&#201;glise.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;R&#233;solu&lt;a class=&quot;headeranchor&quot; id=&quot;R&#233;solu_0&quot; href=&quot;#R&#233;solu_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un &#233;vang&#233;liste consacre ses talents et le plus gros de son apprentissage &#224; l’art des proclamations et non &#224; l’&#233;tude des plus profonds myst&#232;res de sa religion ou &#224; la formation martiale. Il choisit donc un seul domaine et il n’est pas form&#233; au port des &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armures#Intermediaires.html&quot; title=&quot;armure interm&#233;diaire&quot;&gt;armures interm&#233;diaires&lt;/a&gt; ni au maniement du bouclier.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Orateur public&lt;a class=&quot;headeranchor&quot; id=&quot;Orateur_public_1&quot; href=&quot;#Orateur_public_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;L’&#233;vang&#233;liste obtient &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentation.html&quot; title=&quot;Repr&#233;sentation&quot;&gt;Repr&#233;sentation&lt;/a&gt; comme comp&#233;tence de classe. De plus, il s’est entra&#238;n&#233; &#224; faire entendre clairement sa voix de loin, le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; des tests pour l’entendre parler dans des conditions difficiles est r&#233;duit d’un montant &#233;gal &#224; son niveau de + plus son modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; (0 au minimum).&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Sermon public&lt;a class=&quot;headeranchor&quot; id=&quot;Sermon_public_2&quot; href=&quot;#Sermon_public_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;L’&#233;vang&#233;liste peut donner un certain nombre de repr&#233;sentations surnaturelles ou magiques gr&#226;ce &#224; la seule force de ses pr&#234;ches d’inspiration divine. Ce pouvoir est semblable &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Barde.html#REPRESENTATIONBARDIQUE&quot; title=&quot;Le barde&quot;&gt;repr&#233;sentation bardique&lt;/a&gt; d’un &lt;a class=&quot;pagelink&quot; href=&quot;Barde.html&quot; title=&quot;Le barde&quot;&gt;barde&lt;/a&gt; de m&#234;me &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; (y compris en ce qui concerne les interactions avec les dons, les sorts et les classes de prestige). L’&#233;vang&#233;liste se sert de Repr&#233;sentation (arts oratoires) comme comp&#233;tence de repr&#233;sentation. En revanche, l’&#233;vang&#233;liste n’acquiert que les repr&#233;sentations suivantes : &lt;a class=&quot;pagelink&quot; href=&quot;Barde.html#CONTRECHANT&quot; title=&quot;Le barde&quot;&gt;contrechant&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Barde.html#FASCINATION&quot; title=&quot;Le barde&quot;&gt;fascination&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Barde.html#INSPIRATIONVAILLANTE&quot; title=&quot;Le barde&quot;&gt;inspiration vaillante&lt;/a&gt; au niveau 1, &lt;a class=&quot;pagelink&quot; href=&quot;Barde.html#INSPIRATIONGLORIEUSE&quot; title=&quot;Le barde&quot;&gt;inspiration glorieuse&lt;/a&gt; au niveau 9 et &lt;a class=&quot;pagelink&quot; href=&quot;Barde.html#INSPIRATIONHEROIQUE&quot; title=&quot;Le barde&quot;&gt;inspiration h&#233;ro&#239;que&lt;/a&gt; au niveau 15. Le sermon public remplace les pouvoirs de &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre.html#CANALISATIONDENERGIE&quot; title=&quot;Le pr&#234;tre&quot;&gt;canalisation d&#39;&#233;nergie&lt;/a&gt; des niveaux 1, 9 et 15, ce qui limite les d&#233;g&#226;ts de canalisation d’&#233;nergie du pr&#234;tre &#224; 7d6 au maximum.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Incantation spontan&#233;e&lt;a class=&quot;headeranchor&quot; id=&quot;Incantation_spontan&#233;e_3&quot; href=&quot;#Incantation_spontan&#233;e_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;L’&#201;vang&#233;liste ne peut pas lancer de sorts de soins ou de blessure spontan&#233;s en sacrifiant un sort pr&#233;par&#233;. En revanche, il peut lancer l’un des suivants en sacrifiant un sort du niveau indiqu&#233;.&lt;br /&gt;&lt;br /&gt;&lt;center&gt;
&lt;table CLASS=&quot;tablo&quot;&gt;&lt;caption&gt;Incantation spontan&#233;e&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Niveau de sort&lt;/td&gt;&lt;td&gt;Sort de remplacement&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;1&lt;/td&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Injonction.html&quot; title=&quot;Injonction&quot;&gt;injonction&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;&amp;emsp;2&lt;/td&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Discours-Captivant.html&quot; title=&quot;Discours captivant&quot;&gt;discours captivant&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;3&lt;/td&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Don-Des-Langues.html&quot; title=&quot;Don des langues&quot;&gt;don des langues&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;&amp;emsp;4&lt;/td&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Suggestion.html&quot; title=&quot;Suggestion&quot;&gt;suggestion&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;5&lt;/td&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Injonction-Supr&#234;me.html&quot; title=&quot;Injonction supr&#234;me&quot;&gt;injonction supr&#234;me&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;&amp;emsp;6&lt;/td&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Qu&#234;te.html&quot; title=&quot;Qu&#234;te&quot;&gt;qu&#234;te&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;7&lt;/td&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Suggestion-De-Groupe.html&quot; title=&quot;Suggestion de groupe&quot;&gt;suggestion de groupe&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;&amp;emsp;8&lt;/td&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Attirance.html&quot; title=&quot;Attirance&quot;&gt;attirance&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;9&lt;/td&gt;&lt;td&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Exigence.html&quot; title=&quot;Exigence&quot;&gt;exigence&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/center&gt;
